source_code_context:
#include <stdbool.h>

#define MAX_NAS_RETRIES 4

enum nas_state {
    NAS_IDLE,
    NAS_ATTACH_WAIT_ACK,
    NAS_SERVICE_WAIT_ACK
};

struct ue_ctx {
    enum nas_state state;
    unsigned int retry_count;
};

extern void retransmit_pending_nas(struct ue_ctx *ue);
extern void notify_nas_retry_exhausted(struct ue_ctx *ue);

void on_nas_retry_timeout(struct ue_ctx *ue)
{
    if (ue == NULL) {
        return;
    }

    if (ue->state == NAS_ATTACH_WAIT_ACK) {
        if (ue->retry_count < MAX_NAS_RETRIES) {
            ++ue->retry_count;
            retransmit_pending_nas(ue);
        } else {
            ue->state = NAS_IDLE;
            notify_nas_retry_exhausted(ue);
        }
    } else if (ue->state == NAS_SERVICE_WAIT_ACK) {
        if (ue->retry_count < MAX_NAS_RETRIES) {
            ++ue->retry_count;
            retransmit_pending_nas(ue);
        } else {
            ue->state = NAS_IDLE;
            notify_nas_retry_exhausted(ue);
        }
    }
}
